using System.ComponentModel.DataAnnotations;

namespace Nutragea.Commerce.Contracts;
public record CategoryRequest([Required, StringLength(100)] string Name, [Required, RegularExpression("^[a-z0-9]+(?:-[a-z0-9]+)*$"), StringLength(100)] string Slug, bool IsActive, int Version = 0);
public record StoreProductRequest([Required, StringLength(150)] string Name, [Required, RegularExpression("^[a-z0-9]+(?:-[a-z0-9]+)*$"), StringLength(150)] string Slug, [Range(1, long.MaxValue)] long CategoryId, [Range(1, long.MaxValue)] long OperationalProductId, [Required, StringLength(500)] string Summary, [Required, StringLength(15000)] string Description, [Required, StringLength(200)] string Origin, [Required, StringLength(3000)] string Ingredients, [Required, StringLength(3000)] string Allergens, [Required, StringLength(3000)] string Storage, [Required, MaxLength(12)] List<long> ImageIds, bool Published, bool Featured, int Version = 0);
public record VariantRequest([Range(1, long.MaxValue)] long ProductId, [Required, StringLength(100)] string Label, [Required, StringLength(100)] string Sku, [Range(typeof(decimal), "0.01", "10000000")] decimal Price, [Range(typeof(decimal), "0.001", "100")] decimal NetWeightKg, bool IsActive, int Version = 0);
public record AllocationRequest([Range(1, long.MaxValue)] long VariantId, [Range(1, long.MaxValue)] long LotId, [Range(1, 1000000)] int Quantity);
public record ReleaseRequest([Range(1, 1000000)] int Quantity);
public record ContentRequest([Required, RegularExpression("^(Page|Programme|Story|Event|Policy)$")] string Type, [Required, RegularExpression("^[a-z0-9]+(?:-[a-z0-9]+)*$"), StringLength(150)] string Slug, [Required, StringLength(200)] string Title, [StringLength(500)] string Summary, [StringLength(30000)] string Body, [Required, RegularExpression("^(Planned|Active|Completed)$")] string ProgrammeStatus, DateTimeOffset? EventDate, [Required, MaxLength(24)] List<long> ImageIds, bool Published, int Version = 0);
public record ShippingRequest([Required, StringLength(100)] string Name, [Required, RegularExpression("^PK$")] string CountryCode, [Range(typeof(decimal), "0", "1000000")] decimal Charge, bool IsActive, int Version = 0);
public record SettingsRequest(bool CheckoutEnabled, bool CodEnabled, [EmailAddress, StringLength(254)] string? SupportEmail, [StringLength(30)] string? SupportPhone, [StringLength(500)] string? CompanyAddress, int Version);
public record CartLine([Range(1, long.MaxValue)] long VariantId, [Range(1, 100)] int Quantity);
public record QuoteRequest([Required, MinLength(1), MaxLength(30)] List<CartLine> Items, [Range(1, long.MaxValue)] long ShippingId);
public record OrderRequest(Guid RequestId, [Required, MinLength(1), MaxLength(30)] List<CartLine> Items, [Range(1, long.MaxValue)] long ShippingId, [Required, StringLength(150)] string Name, [Required, EmailAddress, StringLength(254)] string Email, [Required, RegularExpression(@"^[+0-9 ()-]{7,30}$")] string Phone, [Required, StringLength(500)] string Address, [Required, StringLength(100)] string City, [Required, StringLength(20)] string PostalCode, [Required, RegularExpression("^PK$")] string CountryCode, [Range(typeof(decimal), "0.01", "1000000000")] decimal ExpectedTotal, bool AcceptTerms, [Required, RegularExpression("^[a-f0-9]{64}$")] string ExpectedPolicyRevision);
public record LookupRequest([Required, StringLength(50)] string Reference, [Required, RegularExpression("^[a-f0-9]{64}$")] string AccessCode);
public record OrderActionRequest([Required, RegularExpression("^(Confirm|Cancel|Ship|Deliver)$")] string Action, [Required, StringLength(1000)] string Reason);
public record EnquiryRequest([Required, RegularExpression("^(Contact|Wholesale)$")] string Type, [Required, StringLength(150)] string Name, [Required, EmailAddress, StringLength(254)] string Email, [StringLength(150)] string? Business, [StringLength(100)] string? Country, [StringLength(500)] string? Products, [StringLength(200)] string? Quantity, [Required, StringLength(10000)] string Message, [StringLength(100)] string? Website);
public record EnquiryStatusRequest([Required, RegularExpression("^(New|Handled)$")] string Status);
public record CartRequest([Required, MinLength(1), MaxLength(30)] List<CartLine> Items);
